function canArchive(role,id){const r=find(role,id);if(!r)throw Error('Record is missing.');const deps={projects:['manuscripts','reports'],manuscripts:['authors','reviews','milestones','submissions','reports'],targets:['manuscripts'],authors:['reviews','manuscripts','submissions'],reviews:['manuscripts','submissions'],milestones:['manuscripts'],submissions:['manuscripts','reports']};const needed=deps[role]||[];if(!complete(needed))throw Error('Dependent evidence cannot be fully read. Archive is blocked.');if(role==='projects'&&(all('manuscripts').some(x=>x.data.projectId===id)||all('reports').some(x=>x.data.projectId===id)))throw Error('Project contains manuscripts or reports.');if(role==='manuscripts'){if(['authors','reviews','milestones','submissions'].some(x=>all(x).some(y=>y.data.manuscriptId===id))||all('reports').some(x=>norm(x.data.references).split(/[\s,;]+/).includes(id)))throw Error('Manuscript has linked evidence; archive dependencies separately.');}if(role==='targets'&&all('manuscripts').some(x=>x.data.targetId===id))throw Error('Target is referenced by a manuscript.');if(['authors','reviews'].includes(role)){const m=find('manuscripts',r.data.manuscriptId);if(m&&['Submitted','Published'].includes(m.data.status))throw Error('A submitted or published manuscript depends on existing approvals.');}if(role==='submissions'){const m=find('manuscripts',r.data.manuscriptId);if(m&&['Submitted','Revision','Published','Withdrawn'].includes(m.data.status))throw Error('Submission evidence supports a current manuscript status.');}if(role==='reports'&&r.data.status==='Reviewed')throw Error('Reviewed reports must be returned to Draft before archival.');return true;}
function proposeRecord(){const e=st.editor;if(!e)throw Error('Editor is closed.');if(!canWrite(e.role))throw Error('Write access is no longer available. Draft retained.');const m=bound[e.role];if(!m)throw Error('Unmapped table.');if(!complete([e.role]))throw Error('Target table is only partially read. Refresh with authorized access.');let d=formValues(e.role,e.draft);if(e.mode==='edit'){const record=find(e.role,e.id);if(!record||record.version!==e.expectedVersion)throw Error('Record changed after editor opened. Draft retained; resolve the conflict.');d={...record.data,...d};}d=checkRecord(e.role,d,e.mode,e.id);const payload={};for(const [k,v] of Object.entries(d))if(k!=='archived'&&m.names[k]&&m.writable.has(k))payload[m.names[k]]=v;if(e.mode==='edit')propose([{kind:'update_record',typeId:m.typeId,recordId:e.id,expectedVersion:e.expectedVersion,data:payload}]);else propose([{kind:'create_record',typeId:m.typeId,data:{...payload,[m.names.archived]:false}}]);}
function archiveRecord(){const c=st.confirm;if(!c)throw Error('Archive confirmation missing.');if(!canWrite(c.role))throw Error('Write access is no longer available.');if(!complete([c.role]))throw Error('Source coverage changed.');const r=find(c.role,c.id);if(!r||r.version!==c.expectedVersion)throw Error('Record changed since archive was opened; no write was proposed.');canArchive(c.role,c.id);const m=bound[c.role];propose([{kind:'update_record',typeId:m.typeId,recordId:c.id,expectedVersion:c.expectedVersion,data:{[m.names.archived]:true}}]);st.confirm=null;}
function cell(role,k,r){let v=r.data[k];if(k==='projectId')return esc(projectName(v));if(k==='manuscriptId')return esc(clip(paperName(v),48));if(k==='targetId')return esc(find('targets',v)?.data.name||'—');if(['status','approval','declaration','decision'].includes(k))return status(v);if(['due','baseline','actualAt','at','targetDate','initialTarget','approvedAt','reviewedAt','verifiedAt','period','cutoff','deadline','publishedAt'].includes(k))return esc(displayDate(v));if(k==='url'||k==='sourceUrl')return safeUrl(v)?'<a class="pm-source" href="'+esc(v)+'" target="_blank" rel="noopener noreferrer">Open source</a>':'—';if(k==='doi')return esc(clip(v,40));if(k==='name')return '<strong class="pm-name">'+esc(clip(v,105))+'</strong>';if(typeof v==='boolean')return v?'Yes':'No';return esc(clip(v,110)||'—');}
function menus(role,r){return '<div class="pm-menu-wrap">'+button(ico('more',17),'menu:'+role+':'+r.id,'icon',false,'aria-label="Actions for '+esc(clip(r.data.name,70))+'" aria-expanded="'+(st.menu===role+':'+r.id)+'"')+(st.menu===role+':'+r.id?'<div class="pm-menu">'+button('Open details','show:'+role+':'+r.id,'menulink')+button('Edit','edit:'+role+':'+r.id,'menulink',!canWrite(role))+button('Duplicate','duplicate:'+role+':'+r.id,'menulink',!canWrite(role))+button('Archive','archive:'+role+':'+r.id,'menulink danger',!canWrite(role))+'</div>':'')+'</div>';}
function table(role,recs,key,empty='No matching records yet.'){const group=templateLayoutSchema.groups[role]||fields[role].slice(0,5).map(f=>({id:f.k,label:f.label})),colIds=cols[role]||group.map(x=>x.id);const p=paginate(recs,key);return '<div class="pm-list"><div class="pm-scroll" role="region" aria-label="'+esc(role)+' register" tabindex="0"><table><thead><tr>'+colIds.map(k=>'<th>'+esc(group.find(x=>x.id===k)?.label||k)+'</th>').join('')+'<th class="pm-row-menu">Actions</th></tr></thead><tbody>'+(p.rows.map(r=>'<tr>'+colIds.map(k=>'<td data-label="'+esc(group.find(x=>x.id===k)?.label||k)+'">'+(k==='name'?button(esc(clip(r.data.name,95)),'show:'+role+':'+r.id,'textlink') : cell(role,k,r))+'</td>').join('')+'<td class="pm-row-menu">'+menus(role,r)+'</td></tr>').join('')||'<tr><td colspan="'+(colIds.length+1)+'" class="pm-empty">'+esc(empty)+'</td></tr>')+'</tbody></table></div>'+paging(key,p)+'</div>';}
